from itertools import combinations


def _route(policy):
    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bits.get(source, 0)
        # State retains visited requirements and coupon use; earliest arrival
        # dominates later arrivals to the same state.
        start = (source, initial_mask, 0)
        best = {start: data["start"]}
        queue = [(data["start"], source, initial_mask, 0)]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full and
                    (policy != "exact" or used == data["coupons"])):
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < data["coupons"]:
                    minimum = 2 if policy in ("at_most_2", "exact_2") else 1
                    duration = max(minimum, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bits.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if next_time < best.get(next_state, float("inf")):
                        best[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(num, den=10000):
        if mode == "half_up":
            return (num + den // 2) // den
        return num // den

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = str(event.get("account", "default")) + "|" + str(event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = {}
    for name in packages:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, []) and
                          (name not in pins or row["version"] == pins[name]))
        choices[name] = [None] + versions

    best_vector = None
    best_assignment = None
    assignment = {}

    def validate():
        # Roots must be installed and satisfy their ranges.
        for name, (low, high) in data["roots"].items():
            version = assignment.get(name)
            if version is None or not low <= version <= high:
                return None
        rows = {name: {row["version"]: row for row in packages[name]}
                for name in packages}
        graph = {name: [] for name, version in assignment.items() if version is not None}
        for name, version in graph.items():
            row = rows[name][assignment[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = assignment.get(target)
                if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                    return None
                graph[name].append(target)

        # Only the active dependency closure of roots may be installed.
        reached = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            stack.extend(graph.get(name, []))
        if reached != set(graph):
            return None

        visiting, finished = set(), set()
        def visit(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            for other in graph[name]:
                if not visit(other):
                    return False
            visiting.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in graph):
            return None
        return tuple(assignment.get(name) if assignment.get(name) is not None else -1
                     for name in names)

    def search(i):
        nonlocal best_vector, best_assignment
        if i == len(names):
            vector = validate()
            if vector is not None and (best_vector is None or vector < best_vector):
                best_vector = vector
                best_assignment = {n: v for n, v in assignment.items() if v is not None}
            return
        name = names[i]
        for version in choices[name]:
            assignment[name] = version
            search(i + 1)
        assignment.pop(name, None)

    search(0)
    if best_assignment is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_assignment}


def _jobs(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None
    for selected in combinations(jobs, k):
        ids = {job["id"] for job in selected}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda job: job["start"])
        if any(a["end"] > b["start"]
               for a, b in zip(ordered, ordered[1:])):
            continue
        value = sum(job["value"] for job in selected)
        chosen_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and chosen_ids < best_ids)):
            best_value, best_ids = value, chosen_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


